module gray_to_binary #(
    parameter int N = 1
)(
    input  logic [N-1:0] gray_i,
    output logic [N-1:0] binary_o
);

    assign binary_o[N-1] = gray_i[N-1];
    for (genvar i = N-2; i >= 0; i--) begin : gen_gray_to_bin
        assign binary_o[i] = binary_o[i+1] ^ gray_i[i];
    end

endmodule

