module cc_onehot #(
    parameter int unsigned NUM_REQ = 1
)(
    input  logic [NUM_REQ-1:0] req_i,
    output logic [NUM_REQ-1:0] gnt_o
);

    logic [NUM_REQ-1:0] masked;

    assign masked[0] = req_i[0];
    for (genvar i = 1; i < NUM_REQ; i++) begin : gen_mask
        assign masked[i] = req_i[i] & ~|req_i[i-1:0];
    end

    assign gnt_o = masked;

endmodule

