module onehot_to_bin #(
    parameter int unsigned ONEHOT_WIDTH = 1
)(
    input  logic [ONEHOT_WIDTH-1:0] onehot_i,
    output logic [$clog2(ONEHOT_WIDTH)-1:0] bin_o
);

    localparam int unsigned BIN_WIDTH = $clog2(ONEHOT_WIDTH);

    for (genvar j = 0; j < BIN_WIDTH; j++) begin : gen_bit
        logic [ONEHOT_WIDTH-1:0] filtered;
        for (genvar i = 0; i < ONEHOT_WIDTH; i++) begin : gen_filter
            assign filtered[i] = onehot_i[i] & i[j];
        end
        assign bin_o[j] = |filtered;
    end

endmodule

