module heaviside #(
    parameter int unsigned WIDTH = 1
)(
    input  logic [WIDTH-1:0]           rev_i,
    output logic [2**WIDTH-1:0]        mask_o
);

    for (genvar i = 0; i < 2**WIDTH; i++) begin : gen_mask
        assign mask_o[i] = (i >= rev_i);
