package cf_math_pkg;

    function automatic integer unsigned cf_length_exp2;
        input integer unsigned depth;
        integer unsigned i;
    begin
        i = 1;
        while (2**i < depth) begin
            i = i + 1;
        end
        cf_length_exp2 = i;
    end
    endfunction

endpackage

