module sync #(
    parameter int unsigned STAGES = 2
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic serial_i,
    output logic serial_o
);

    logic [STAGES-1:0] reg_q;

    `FF(reg_q[0], serial_i, '0)

    for (genvar i = 1; i < STAGES; i++) begin : gen_sync
        `FF(reg_q[i], reg_q[i-1], '0)
    end

    assign serial_o = reg_q[STAGES-1];

endmodule

