module serial_deglitch #(
    parameter int unsigned CYCLES = 3
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic serial_i,
    output logic serial_o
);

    logic [$clog2(CYCLES)-1:0] counter_q;
    logic                      counter_overflow;

    assign counter_overflow = (counter_q == CYCLES[{$clog2(CYCLES)}:0] - 1);

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            counter_q <= '0;
        end else begin
            if (serial_i != serial_o) begin
                counter_q <= counter_q + 1;
            end else begin
                counter_q <= '0;
            end
        end
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            serial_o <= 1'b0;
        end else begin
            if (counter_overflow) begin
                serial_o <= serial_i;
            end
        end
    end

endmodule

