module credit_counter #(
    parameter int unsigned MAX_CREDIT = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic incr_i,
    input  logic decr_i,
    output logic [cf_math_pkg::cf_length_exp2(MAX_CREDIT+1)-1:0] credit_o,
    output logic full_o
);

    localparam int unsigned CNT_WIDTH = cf_math_pkg::cf_length_exp2(MAX_CREDIT+1);

    logic [CNT_WIDTH-1:0] cnt_q;

    `FF(cnt_q, cnt_q + {{(CNT_WIDTH-1){1'b0}}, incr_i} - {{(CNT_WIDTH-1){1'b0}}, decr_i}, '0)

    assign credit_o = cnt_q;
    assign full_o   = (cnt_q == MAX_CREDIT[CNT_WIDTH-1:0]);

endmodule

