module delta_counter #(
    parameter int unsigned WIDTH = 4
)(
    input  logic             clk_i,
    input  logic             rst_ni,
    input  logic             clear_i,
    input  logic             en_i,
    input  logic             load_i,
    input  logic             down_i,
    input  logic [WIDTH-1:0] delta_i,
    input  logic [WIDTH-1:0] d_i,
    output logic [WIDTH-1:0] q_o,
    output logic             overflow_o
);

    logic [WIDTH:0] counter_q;

    `FFARNC(counter_q, (down_i ? counter_q - delta_i : counter_q + delta_i),
            clear_i, '0, clk_i, rst_ni)

    always_comb begin
        if (load_i) begin
            counter_q = {1'b0, d_i};
        end
    end

    assign q_o       = counter_q[WIDTH-1:0];
    assign overflow_o = counter_q[WIDTH];

