module delta_counter #(
    parameter int unsigned WIDTH = 4
)(
    input  logic             clk_i,
    input  logic             rst_ni,
    input  logic             clear_i,
    input  logic             en_i,
    input  logic             load_i,
    input  logic             down_i,
    input  logic [WIDTH-1:0] delta_i,
    input  logic [WIDTH-1:0] d_i,
    output logic [WIDTH-1:0] q_o,
    output logic             overflow_o
);

    logic [WIDTH-1:0] cnt_d, cnt_q;

    always_comb begin
        cnt_d = cnt_q;
        if (load_i) begin
            cnt_d = d_i;
        end else if (en_i) begin
            if (down_i) begin
                cnt_d = cnt_q - delta_i;
            end else begin
                cnt_d = cnt_q + delta_i;
            end
        end
    end

    `FFLARNC(cnt_q, cnt_d, (load_i | en_i), clear_i, '0, clk_i, rst_ni)

    assign q_o       = cnt_q;
    assign overflow_o = (cnt_q < delta_i) & down_i & en_i & !load_i;

endmodule

