module credit_counter #(
    parameter int unsigned MAX_CREDIT = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic incr_i,
    input  logic decr_i,
    output logic [$clog2(MAX_CREDIT+1)-1:0] credit_o,
    output logic full_o
);

    localparam int unsigned CNT_WIDTH = $clog2(MAX_CREDIT+1);

    logic [CNT_WIDTH-1:0] cnt_d, cnt_q;

    always_comb begin
        cnt_d = cnt_q;
        if (incr_i && !decr_i && !full_o) begin
            cnt_d = cnt_q + 1;
        end else if (decr_i && !incr_i && cnt_q > 0) begin
            cnt_d = cnt_q - 1;
        end
    end

    `FF(cnt_q, cnt_d, '0)

    assign credit_o = cnt_q;
    assign full_o   = (cnt_q == MAX_CREDIT[CNT_WIDTH-1:0]);

endmodule

