module stream_throttle #(
    parameter int unsigned MAX_CNT = 1
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic valid_i,
    output logic ready_o,
    output logic valid_o,
    input  logic ready_i
);

    localparam int unsigned CNT_WIDTH = $clog2(MAX_CNT + 1);

    logic [CNT_WIDTH-1:0] cnt_q, cnt_d;
