module exp_backoff #(
    parameter int unsigned MAX_EXP = 8
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic coll_i,
    output logic valid_o
);

    localparam int unsigned CNT_WIDTH = $clog2(MAX_EXP + 1);

    logic [CNT_WIDTH-1:0] exp_q, exp_d;
    logic [CNT_WIDTH-1:0] cnt_q, cnt_d;
    logic                 expired;

    assign expired = (cnt_q == '0);

    always_comb begin
        exp_d = exp_q;
        if (coll_i && expired) begin
            if (exp_q < MAX_EXP[CNT_WIDTH-1:0]) begin
                exp_d = exp_q + 1;
            end
        end
    end

    always_comb begin
        cnt_d = cnt_q;
        if (expired) begin
            cnt_d = exp_q;
        end else begin
            cnt_d = cnt_q - 1;
        end
    end

    `FF(exp_q, exp_d, '0)
    `FF(cnt_q, cnt_d, '0)

    assign valid_o = expired;

endmodule

