module lossy_valid_to_stream #(
    parameter type DATA_T = logic
)(
    input  logic  clk_i,
    input  logic  rst_ni,
    input  DATA_T data_i,
    input  logic  valid_i,
    output logic  ready_o,
    output DATA_T data_o,
    output logic  valid_o,
    input  logic  ready_i
);

    logic [1:0] state_q;
    logic [1:0] state_d;

    localparam logic [1:0] IDLE    = 2'b00;
    localparam logic [1:0] VALID   = 2'b01;
    localparam logic [1:0] UPDATE  = 2'b10;

    always_comb begin
        state_d = state_q;
        valid_o = 1'b0;
        ready_o = 1'b0;
        case (state_q)
            IDLE: begin
                if (valid_i) begin
                    valid_o = 1'b1;
                    if (ready_i) begin
                        state_d = IDLE;
                        ready_o = 1'b1;
                    end else begin
                        state_d = VALID;
                    end
                end
            end
            VALID: begin
                valid_o = 1'b1;
                if (ready_i) begin
                    if (valid_i) begin
                        state_d = UPDATE;
                    end else begin
                        state_d = IDLE;
                    end
                end
            end
            UPDATE: begin
                ready_o = 1'b1;
                state_d = IDLE;
            end
            default: state_d = IDLE;
        endcase
    end

    `FF(state_q, state_d, IDLE)

    assign data_o = data_i;

endmodule

