module isochronous_4phase_handshake #(
    parameter type DATA_T = logic
)(
    input  logic  clk_src_i,
    input  logic  rst_src_ni,
    input  logic  clk_dst_i,
    input  logic  rst_dst_ni,
    input  DATA_T data_i,
    input  logic  valid_src_i,
    output logic  ready_src_o,
    output DATA_T data_o,
    output logic  valid_dst_o,
    input  logic  ready_dst_i
);

    logic req_src, ack_src;
    logic req_dst, ack_dst;
    DATA_T data_q;

    `FF(data_q, data_i, '0, clk_src_i, rst_src_ni)

    assign ready_src_o = ~req_src | ack_src;

    always_ff @(posedge clk_src_i or negedge rst_src_ni) begin
        if (!rst_src_ni) begin
            req_src <= 1'b0;
        end else begin
            if (valid_src_i && ready_src_o) begin
                req_src <= 1'b1;
            end else if (!valid_src_i && req_src && ack_src) begin
                req_src <= 1'b0;
            end
        end
    end

    sync #(.STAGES(2)) i_sync_req (
        .clk_i    (clk_dst_i),
        .rst_ni   (rst_dst_ni),
        .serial_i (req_src),
        .serial_o (req_dst)
    );

    sync #(.STAGES(2)) i_sync_ack (
        .clk_i    (clk_src_i),
        .rst_ni   (rst_src_ni),
        .serial_i (ack_dst),
        .serial_o (ack_src)
    );

    assign valid_dst_o = req_dst & ~ready_dst_i;
    assign data_o      = data_q;

    always_ff @(posedge clk_dst_i or negedge rst_dst_ni) begin
        if (!rst_dst_ni) begin
            ack_dst <= 1'b0;
        end else begin
            if (req_dst && ready_dst_i) begin
                ack_dst <= 1'b1;
            end else if (!req_dst) begin
                ack_dst <= 1'b0;
            end
        end
    end

endmodule

