module lfsr #(
    parameter int unsigned LfsrDw       = 8,
    parameter int unsigned OutDw        = 8,
    parameter int unsigned StateSizeDw  = LfsrDw,
    parameter bit          Whitening     = 0,
    parameter logic [LfsrDw-1:0] Seed          = '0,
    parameter logic [LfsrDw-1:0] LfsrPoly      = '0
)(
    input  logic                    clk_i,
    input  logic                    rst_ni,
    input  logic                    en_i,
    output logic [OutDw-1:0]        data_o
);

    logic [LfsrDw-1:0] lfsr_q, lfsr_d;
    logic [OutDw-1:0]  out;

    always_comb begin
        lfsr_d = lfsr_q;
        if (en_i) begin
            lfsr_d[0] = lfsr_q[LfsrDw-1];
            for (int unsigned i = 1; i < LfsrDw; i++) begin
                lfsr_d[i] = lfsr_q[i-1] ^ (lfsr_q[LfsrDw-1] & LfsrPoly[i]);
            end
        end
    end

    `FF(lfsr_q, lfsr_d, Seed)

    if (Whitening) begin : gen_whitening
    for (genvar i = 0; i < OutDw; i++) begin : gen_out
        localparam int unsigned IDX = i % LfsrDw;
        assign out[i] = lfsr_q[IDX] ^ 1'b1;
    end
    end else begin : gen_no_whitening
    for (genvar i = 0; i < OutDw; i++) begin : gen_out
        localparam int unsigned IDX = i % LfsrDw;
        assign out[i] = lfsr_q[IDX];
    end
    end

    assign data_o = out;

endmodule

