module shift_reg #(
    parameter type         DATA_T = logic,
    parameter int unsigned DEPTH  = 8
)(
    input  logic  clk_i,
    input  logic  rst_ni,
    input  DATA_T data_i,
    input  logic  valid_i,
    output DATA_T data_o,
    output logic  valid_o
);

    DATA_T [DEPTH-1:0] reg_q;

    `FF(reg_q[0], data_i, '0)
