module fifo_v3 #(
    parameter bit           FALL_THROUGH = 1'b0,
    parameter int unsigned  DATA_WIDTH   = 32,
    parameter int unsigned  DEPTH        = 8,
    localparam int unsigned ADDR_DEPTH   = (DEPTH > 1) ? $clog2(DEPTH) : 1
)(
    input  logic                    clk_i,
    input  logic                    rst_ni,
    input  logic                    flush_i,
    input  logic                    testmode_i,
    output logic                    full_o,
    output logic                    empty_o,
    output logic [ADDR_DEPTH-1:0]   usage_o,
    input  logic [DATA_WIDTH-1:0]   data_i,
    input  logic                    push_i,
    output logic [DATA_WIDTH-1:0]   data_o,
    input  logic                    pop_i
);

    localparam int unsigned FIFO_SIZE = (DEPTH > 1) ? DEPTH : 1;

    logic [ADDR_DEPTH-1:0]   read_ptr_q,  read_ptr_d;
    logic [ADDR_DEPTH-1:0]   write_ptr_q, write_ptr_d;
    logic [ADDR_DEPTH:0]     cnt_q, cnt_d;
    logic                    push, pop;

    assign push = push_i & ~full_o;
    assign pop  = pop_i  & ~empty_o;

    always_comb begin
        cnt_d       = cnt_q;
        read_ptr_d  = read_ptr_q;
        write_ptr_d = write_ptr_q;
        if (push && !pop) begin
            cnt_d       = cnt_q + 1;
            write_ptr_d = write_ptr_q + 1;
        end else if (!push && pop) begin
            cnt_d      = cnt_q - 1;
            read_ptr_d = read_ptr_q + 1;
        end else if (push && pop) begin
            write_ptr_d = write_ptr_q + 1;
            read_ptr_d  = read_ptr_q + 1;
        end
    end

    `FF(cnt_q, cnt_d, '0)
    `FF(read_ptr_q, read_ptr_d, '0)
    `FF(write_ptr_q, write_ptr_d, '0)

    assign full_o  = (cnt_q == FIFO_SIZE[ADDR_DEPTH:0]);
    assign empty_o = (cnt_q == '0);
    assign usage_o = cnt_q[ADDR_DEPTH-1:0];

    logic [DATA_WIDTH-1:0] mem [FIFO_SIZE-1:0];
    logic [DATA_WIDTH-1:0] data_out;

    always_ff @(posedge clk_i) begin
        if (push) begin
            mem[write_ptr_q[ADDR_DEPTH-1:0]] <= data_i;
        end
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            data_out <= '0;
        end else begin
            if (FALL_THROUGH) begin
                if (push && empty_o) begin
                    data_out <= data_i;
                end else if (pop) begin
                    data_out <= mem[read_ptr_d[ADDR_DEPTH-1:0]];
                end
            end else begin
                if (pop || (empty_o && push)) begin
                    data_out <= mem[read_ptr_d[ADDR_DEPTH-1:0]];
                end
            end
        end
    end

    assign data_o = data_out;

endmodule

