module plru_tree #(
    parameter int unsigned ENTRIES = 4
)(
    input  logic                        clk_i,
    input  logic                        rst_ni,
    input  logic [ENTRIES-1:0]          access_i,
    input  logic                        update_i,
    output logic [ENTRIES-1:0]          hit_oh,
    output logic [$clog2(ENTRIES)-1:0]  valid_oh
);

    localparam int unsigned LOG_ENTRIES = $clog2(ENTRIES);
    localparam int unsigned NUM_NODES   = ENTRIES - 1;

    logic [NUM_NODES-1:0] plru_tree_q, plru_tree_d;

    always_comb begin
        plru_tree_d = plru_tree_q;
        if (update_i) begin
            for (int unsigned i = 0; i < ENTRIES; i++) begin
                if (access_i[i]) begin
                    logic [LOG_ENTRIES-1:0] idx;
                    idx = i[LOG_ENTRIES-1:0];
                    for (int unsigned lvl = 0; lvl < LOG_ENTRIES; lvl++) begin
                        logic [NUM_NODES-1:0] node_idx;
                        node_idx = (NUM_NODES >> (lvl+1)) + (idx >> (LOG_ENTRIES - lvl));
                        plru_tree_d[node_idx] = idx[LOG_ENTRIES-1-lvl];
                    end
                end
            end
        end
    end

    `FF(plru_tree_q, plru_tree_d, '0)

    logic [LOG_ENTRIES-1:0] replace_idx;
    always_comb begin
        replace_idx = '0;
        for (int unsigned lvl = 0; lvl < LOG_ENTRIES; lvl++) begin
            replace_idx[LOG_ENTRIES-1-lvl] = ~plru_tree_q[(NUM_NODES >> (lvl+1)) + replace_idx >> (LOG_ENTRIES - lvl)];
        end
    end

    assign hit_oh   = '0;
    assign valid_oh = replace_idx;

endmodule

