module rr_arb_tree #(
    parameter int unsigned NumIn     = 4,
    parameter int unsigned DataWidth = 32,
    parameter bit          ExtPrio   = 1'b0,
    parameter bit          AxiVldRdy = 1'b1,
    parameter bit          LockIn    = 1'b0,
    parameter bit          FairArb   = 1'b0
)(
    input  logic                        clk_i,
    input  logic                        rst_ni,
    input  logic                        flush_i,
    input  logic [$clog2(NumIn)-1:0]    rr_i,
    input  logic [NumIn-1:0]            req_i,
    output logic [NumIn-1:0]            gnt_o,
    input  logic [NumIn-1:0][DataWidth-1:0] data_i,
    input  logic                        gnt_i,
    output logic                        req_o,
    output logic [DataWidth-1:0]        data_o,
    output logic [$clog2(NumIn)-1:0]    idx_o
);

    localparam int unsigned IdxWidth = (NumIn > 1) ? $clog2(NumIn) : 1;

    logic [NumIn-1:0] req;
    logic [NumIn-1:0] gnt;
    logic [IdxWidth-1:0] rr_q, rr_d;
    logic [IdxWidth-1:0] idx;

    assign req = req_i;

    always_comb begin
        gnt   = '0;
        idx   = '0;
        rr_d  = rr_q;

        for (int unsigned i = 0; i < NumIn; i++) begin
            if (req[i]) begin
                idx = IdxWidth'(i);
            end
        end

        if (ExtPrio) begin
            idx = rr_i;
        end else begin
            for (int unsigned i = 0; i < NumIn; i++) begin
                logic [IdxWidth-1:0] check_idx;
                check_idx = (rr_q + IdxWidth'(i)) % IdxWidth'(NumIn);
                if (req[check_idx]) begin
                    idx = check_idx;
                    break;
                end
            end
        end

        if (AxiVldRdy) begin
            if (req[idx] && gnt_i) begin
                gnt[idx] = 1'b1;
                rr_d = idx + 1;
            end
        end else begin
            if (req[idx]) begin
                gnt[idx] = 1'b1;
                rr_d = idx + 1;
            end
        end
    end

    if (!ExtPrio) begin : gen_rr_reg
        `FF(rr_q, rr_d, '0)
    end else begin : gen_no_rr_reg
        assign rr_q = rr_i;
    end

    assign gnt_o  = gnt;
    assign req_o  = |req;
    assign data_o = data_i[idx];
    assign idx_o  = idx;

endmodule

