module sub_per_hash #(
    parameter int unsigned InpWidth   = 8,
    parameter int unsigned HashWidth  = 4,
    parameter int unsigned NoRounds   = 1,
    parameter logic [31:0] PermuteKey = 32'h0,
    parameter logic [31:0] XorKey    = 32'h0
)(
    input  logic [InpWidth-1:0]            data_i,
    output logic [HashWidth-1:0]           hash_o,
    output logic [2**HashWidth-1:0]        hash_onehot_o
);

    logic [InpWidth-1:0] state;

    always_comb begin
        state = data_i;
        for (int unsigned r = 0; r < NoRounds; r++) begin
            logic [InpWidth-1:0] permuted;
            for (int unsigned i = 0; i < InpWidth; i++) begin
                logic [4:0] src_bit;
                src_bit = 5'(i * PermuteKey + r);
                permuted[i] = state[src_bit % InpWidth];
            end
            state = permuted;
            for (int unsigned i = 0; i < InpWidth; i++) begin
                if (i < HashWidth) begin
                    state[i] = state[i] ^ XorKey[i % 32];
                end
            end
        end
    end

    assign hash_o = state[HashWidth-1:0];

    for (genvar i = 0; i < 2**HashWidth; i++) begin : gen_onehot
        assign hash_onehot_o[i] = (hash_o == i[HashWidth-1:0]);
    end

endmodule

