module clk_int_div #(
    parameter int unsigned DIV_VALUE = 2
)(
    input  logic clk_i,
    input  logic rst_ni,
    input  logic testmode_i,
    input  logic en_i,
    output logic clk_o,
    input  logic [31:0] div_i,
    output logic cyc_cnt_o
);

    logic [31:0] counter_q, counter_d;
    logic        clk_q, clk_d;
    logic        div_by_two;
    logic        div_even;
    logic [31:0] div_cnt;
    logic        reload;

    assign div_cnt    = (div_i > 0) ? div_i : DIV_VALUE[31:0];
    assign div_by_two = (div_cnt == 32'd2);
    assign div_even   = (div_cnt[0] == 1'b0);
    assign reload     = (counter_q >= div_cnt - 1);

    always_comb begin
        counter_d = counter_q;
        clk_d     = clk_q;
        if (en_i) begin
            if (reload) begin
                counter_d = '0;
                clk_d     = ~clk_q;
            end else begin
                counter_d = counter_q + 1;
            end
        end
    end

    `FF(counter_q, counter_d, '0)
    `FF(clk_q, clk_d, '0)

    logic clk_out;
    tc_clk_mux2 i_clk_mux (
        .clk0_i   (clk_q),
        .clk1_i   (~clk_q),
        .clk_sel_i(div_even),
        .clk_o    (clk_out)
    );

    logic clk_div;
    tc_clk_xor2 i_clk_xor (
        .clk0_i(clk_q),
        .clk1_i(clk_out),
        .clk_o (clk_div)
    );

    tc_clk_mux2 i_clk_out_mux (
        .clk0_i   (clk_div),
        .clk1_i   (clk_q),
        .clk_sel_i(div_by_two),
        .clk_o    (clk_o)
    );

    assign cyc_cnt_o = reload;

endmodule

