module ecc_encode #(
    parameter bit ENCODE = 1'b1
)(
    input  logic [63:0]  data_i,
    output logic [71:0]  data_o
);

    localparam int unsigned D = 64;
    localparam int unsigned P = 7;

    logic [D+P:0] codeword;

    logic is_power_of_2 [D+P:1];

    for (genvar i = 1; i <= D + P; i++) begin : gen_pow2_check
        assign is_power_of_2[i] = (i != 0) && ((i & (i - 1)) == 0);
    end

    always_comb begin
        automatic int idx = 0;
        codeword = '0;

        for (int i = 1; i <= D + P; i++) begin
            if (!is_power_of_2[i]) begin
                codeword[i-1] = data_i[idx];
                idx++;
            end
        end

        for (int i = 0; i < P; i++) begin
            automatic logic parity = 0;
            for (int k = 1; k <= D + P; k++) begin
                if (k & (1 << i)) begin
                    parity = parity ^ codeword[k-1];
                end
            end
            codeword[(1 << i) - 1] = parity;
        end

        codeword[D + P] = '0;
        for (int i = 0; i < D + P; i++) begin
            codeword[D + P] = codeword[D + P] ^ codeword[i];
        end
    end

    assign data_o = codeword;

endmodule

