    parameter bit DECODE = 1'b1
)(
    input  logic [71:0]  data_i,
    output logic [63:0]  data_o,
    output logic         single_error_o,
    output logic         parity_error_o,
    output logic         double_error_o
);

    localparam int unsigned D = 64;
    localparam int unsigned P = 7;

    logic [P-1:0] syndrome;
    logic overall_parity;

    always_comb begin
        for (int i = 0; i < P; i++) begin
            syndrome[i] = 0;
            for (int k = 1; k <= D + P; k++) begin
                if (k & (1 << i)) begin
                    syndrome[i] = syndrome[i] ^ data_i[k-1];
                end
            end
        end
    end

    always_comb begin
        overall_parity = 0;
        for (int i = 0; i < D + P + 1; i++) begin
            overall_parity = overall_parity ^ data_i[i];
        end
    end

    logic [D+P:0] corrected;
    logic is_power_of_2 [D+P:1];

    for (genvar i = 1; i <= D + P; i++) begin : gen_pow2_check
        assign is_power_of_2[i] = (i != 0) && ((i & (i - 1)) == 0);
    end

    always_comb begin
        corrected = data_i[D+P:0];

        if (|syndrome && overall_parity) begin
            if (!is_power_of_2[syndrome]) begin
                corrected[syndrome - 1] = ~data_i[syndrome - 1];
            end
        end
    end

    always_comb begin
        automatic int idx = 0;
        data_o = '0;
        for (int i = 1; i <= D + P; i++) begin
            if (!is_power_of_2[i]) begin
                data_o[idx] = corrected[i-1];
                idx++;
            end
        end
    end

    assign single_error_o = |syndrome & overall_parity;
    assign parity_error_o = ~(|syndrome) & overall_parity;
    assign double_error_o = |syndrite & ~overall_parity;

endmodule

