    always_comb begin
        for (int i = 0; i < P; i++) begin
            syndrome[i] = 0;
            for (int k = 1; k <= D + P; k++) begin
                if (k & (1 << i)) begin
                    syndrome[i] = syndrome[i] ^ data_i[k-1];
