module cdc_2phase #(
    parameter type DATA_T = logic
)(
    input  logic  clk_src_i,
    input  logic  rst_src_ni,
    input  DATA_T data_src_i,
    input  logic  valid_src_i,
    output logic  ready_src_o,
    input  logic  clk_dst_i,
    input  logic  rst_dst_ni,
    output DATA_T data_dst_o,
    output logic  valid_dst_o,
    input  logic  ready_dst_i
);

    logic async_req, async_ack;
    logic req_src, ack_dst, req_dst, ack_src;

    logic valid_src, ready_src;
    assign valid_src = valid_src_i;

    always_ff @(posedge clk_src_i or negedge rst_src_ni) begin
        if (!rst_src_ni) begin
            req_src <= 1'b0;
        end else begin
            if (valid_src && ready_src_o) begin
                req_src <= ~req_src;
            end
        end
    end

    always_ff @(posedge clk_src_i or negedge rst_src_ni) begin
        if (!rst_src_ni) begin
            data_dst_o <= '0;
        end else begin
            if (valid_src && ready_src_o) begin
                data_dst_o <= data_src_i;
            end
        end
    end

    sync #(.STAGES(2)) i_sync_req (
        .clk_i    (clk_dst_i),
        .rst_ni   (rst_dst_ni),
        .serial_i (req_src),
        .serial_o (req_dst)
    );

    sync #(.STAGES(2)) i_sync_ack (
        .clk_i    (clk_src_i),
        .rst_ni   (rst_src_ni),
        .serial_i (ack_dst),
        .serial_o (ack_src)
    );

    assign async_req = req_src;
    assign async_ack = ack_dst;

    assign ready_src_o = (req_src == ack_src);
    assign valid_dst_o = (req_dst != ack_dst);

    always_ff @(posedge clk_dst_i or negedge rst_dst_ni) begin
        if (!rst_dst_ni) begin
            ack_dst <= 1'b0;
        end else begin
            if (valid_dst_o && ready_dst_i) begin
                ack_dst <= ~ack_dst;
            end
        end
    end

endmodule

