module max_counter #(
    parameter int unsigned WIDTH = 4
)(
    input  logic             clk_i,
    input  logic             rst_ni,
    input  logic             clear_i,
    input  logic             en_i,
    input  logic             load_i,
    input  logic             down_i,
    input  logic [WIDTH-1:0] delta_i,
    input  logic [WIDTH-1:0] d_i,
    output logic [WIDTH-1:0] q_o,
    output logic [WIDTH-1:0] max_o,
    output logic             overflow_o
);

    logic [WIDTH-1:0] cnt_q, cnt_d, max_q, max_d;

    always_comb begin
        cnt_d = cnt_q;
        if (load_i) begin
            cnt_d = d_i;
        end else if (en_i) begin
            if (down_i) begin
                cnt_d = cnt_q - delta_i;
            end else begin
                cnt_d = cnt_q + delta_i;
            end
        end
    end

    always_comb begin
        max_d = max_q;
        if (clear_i) begin
            max_d = '0;
        end else if (load_i) begin
            if (d_i > max_q) max_d = d_i;
        end else if (en_i && !down_i && (cnt_q + delta_i > max_q)) begin
            max_d = cnt_q + delta_i;
        end
    end

    `FFLARNC(cnt_q, cnt_d, (load_i | en_i), clear_i, '0, clk_i, rst_ni)
    `FFLARNC(max_q, max_d, (load_i | en_i | clear_i), 1'b0, '0, clk_i, rst_ni)

    assign q_o       = cnt_q;
    assign max_o     = max_q;
    assign overflow_o = (cnt_q < delta_i) & down_i & en_i & !load_i;

endmodule

