module lzc #(
    parameter int unsigned WIDTH = 64,
    parameter bit          MODE  = 1'b0
)(
    input  logic [WIDTH-1:0]         in_i,
    output logic [$clog2(WIDTH)-1:0] cnt_o,
    output logic                     empty_o
);

    localparam int unsigned NUM_LEVELS = $clog2(WIDTH);

    logic [WIDTH-1:0][NUM_LEVELS-1:0] index_lut;

    for (genvar j = 0; j < WIDTH; j++) begin : gen_index_lut
        assign index_lut[j] = NUM_LEVELS'(j);
    end

    logic [2**NUM_LEVELS-1:0] sel_nodes;
    logic [2**NUM_LEVELS-1:0][NUM_LEVELS-1:0] index_nodes;

    for (genvar l = 0; l < NUM_LEVELS; l++) begin : gen_levels
        for (genvar k = 0; k < 2**l; k++) begin : gen_level
            localparam int unsigned IDX = 2**l + k;
            localparam int unsigned LEFT = 2 * k;
            localparam int unsigned RIGHT = 2 * k + 1;

            if (l == 0) begin : gen_leaf
                if (MODE == 1'b0) begin : gen_lzc
                    assign sel_nodes[IDX]   = in_i[k];
                    assign index_nodes[IDX] = index_lut[k];
                end else begin : gen_msb
                    assign sel_nodes[IDX]   = in_i[WIDTH-1-k];
                    assign index_nodes[IDX] = index_lut[WIDTH-1-k];
                end
            end else begin : gen_inner
                logic sel_left, sel_right;
                assign sel_left  = sel_nodes[LEFT];
                assign sel_right = sel_nodes[RIGHT];

                if (MODE == 1'b0) begin : gen_lzc
                    assign sel_nodes[IDX]   = sel_left | sel_right;
                    assign index_nodes[IDX] = sel_left ? index_nodes[LEFT] : index_nodes[RIGHT];
                end else begin : gen_msb
                    assign sel_nodes[IDX]   = sel_left | sel_right;
                    assign index_nodes[IDX] = sel_right ? index_nodes[RIGHT] : index_nodes[LEFT];
                end
            end
        end
    end

    assign cnt_o   = index_nodes[1];
    assign empty_o = ~sel_nodes[1];

endmodule

