module stream_delay #(
    parameter int unsigned DELAY = 1,
    parameter type         DATA_T = logic
)(
    input  logic  clk_i,
    input  logic  rst_ni,
    input  logic  valid_i,
    output logic  ready_o,
    input  DATA_T data_i,
    output logic  valid_o,
    input  logic  ready_i,
    output DATA_T data_o
);

    localparam int unsigned CNT_WIDTH = (DELAY > 0) ? $clog2(DELAY + 1) : 1;

    logic [CNT_WIDTH-1:0] cnt_q, cnt_d;
    logic                 fire;

    assign fire    = valid_i & ready_o;
    assign cnt_d   = (fire) ? ((cnt_q == DELAY[CNT_WIDTH-1:0]) ? DELAY[CNT_WIDTH-1:0] : cnt_q + 1) : cnt_q;

    `FF(cnt_q, cnt_d, '0)

    assign valid_o = valid_i & (cnt_q == DELAY[CNT_WIDTH-1:0]);
    assign ready_o = ready_i & (cnt_q == DELAY[CNT_WIDTH-1:0]);
    assign data_o  = data_i;

endmodule

