module stream_fork_dynamic #(
    parameter int unsigned N_OUP = 2,
    parameter type         DATA_T = logic
)(
    input  logic  clk_i,
    input  logic  rst_ni,
    input  DATA_T data_i,
    input  logic  valid_i,
    output logic  ready_o,
    output DATA_T [N_OUP-1:0] data_o,
    output logic [N_OUP-1:0]  valid_o,
    input  logic [N_OUP-1:0]  ready_i,
    input  logic [N_OUP-1:0]  sel_i
);

    logic [N_OUP-1:0] done_q;

    logic all_done;
    assign all_done = &(done_q | ~sel_i);

    logic [N_OUP-1:0] done_d;
    for (genvar i = 0; i < N_OUP; i++) begin : gen_done
        assign done_d[i] = done_q[i] | (valid_o[i] & ready_i[i]);
    end

    `FF(done_q, (valid_i & ready_o) ? '0 : done_d, '0)

    for (genvar i = 0; i < N_OUP; i++) begin : gen_output
        assign valid_o[i] = valid_i & ~done_q[i] & sel_i[i];
        assign data_o[i]  = data_i;
    end

    assign ready_o = all_done;

endmodule

