module cdc_fifo_2phase #(
    parameter int unsigned LOG_DEPTH = 3,
    parameter type         DATA_T   = logic
)(
    input  logic  clk_src_i,
    input  logic  rst_src_ni,
    input  DATA_T data_src_i,
    input  logic  valid_src_i,
    output logic  ready_src_o,
    input  logic  clk_dst_i,
    input  logic  rst_dst_ni,
    output DATA_T data_dst_o,
    output logic  valid_dst_o,
    input  logic  ready_dst_i
);

    localparam int unsigned DEPTH = 2**LOG_DEPTH;

    logic [LOG_DEPTH:0] wptr_q, wptr_d, rptr_sync;
    logic [LOG_DEPTH:0] rptr_q, rptr_d, wptr_sync;
    DATA_T mem [DEPTH-1:0];

    sync #(.STAGES(2)) i_sync_rptr (
        .clk_i    (clk_src_i),
        .rst_ni   (rst_src_ni),
        .serial_i (rptr_q[LOG_DEPTH]),
        .serial_o (rptr_sync[LOG_DEPTH])
    );

    sync #(.STAGES(2)) i_sync_wptr (
        .clk_i    (clk_dst_i),
        .rst_ni   (rst_dst_ni),
        .serial_i (wptr_q[LOG_DEPTH]),
        .serial_o (wptr_sync[LOG_DEPTH])
    );

    assign ready_src_o = (wptr_q[LOG_DEPTH] == rptr_sync[LOG_DEPTH]) ||
                         (wptr_q[LOG_DEPTH-1:0] != rptr_sync[LOG_DEPTH-1:0]);

    always_ff @(posedge clk_src_i or negedge rst_src_ni) begin
        if (!rst_src_ni) begin
            wptr_q <= '0;
        end else if (valid_src_i && ready_src_o) begin
            wptr_q <= wptr_q + 1;
            mem[wptr_q[LOG_DEPTH-1:0]] <= data_src_i;
        end
    end

    assign valid_dst_o = (wptr_sync[LOG_DEPTH] != rptr_q[LOG_DEPTH]) ||
                         (wptr_sync[LOG_DEPTH-1:0] != rptr_q[LOG_DEPTH-1:0]);

    always_ff @(posedge clk_dst_i or negedge rst_dst_ni) begin
        if (!rst_dst_ni) begin
            rptr_q <= '0;
            data_dst_o <= '0;
        end else if (valid_dst_o && ready_dst_i) begin
            rptr_q <= rptr_q + 1;
            data_dst_o <= mem[rptr_q[LOG_DEPTH-1:0]];
        end
    end

endmodule

