module cb_filter #(
    parameter int unsigned HASH_TABLE_SIZE = cb_filter_pkg::HASH_TABLE_SIZE,
    parameter int unsigned KEY_WIDTH       = cb_filter_pkg::KEY_WIDTH,
    parameter int unsigned HASH_CNT_WIDTH  = 4,
    parameter cb_filter_pkg::cb_seed_t [2**KEY_WIDTH-1:0] Seeds = '{default: '0}
)(
    input  logic                    clk_i,
    input  logic                    rst_ni,
    input  logic                    clear_i,
    input  logic                    lookup_i,
    input  logic [KEY_WIDTH-1:0]    key_i,
    output logic                    hit_o,
    input  logic                    insert_i,
    input  logic                    delete_i
);

    localparam int unsigned HASH_IDX_WIDTH = $clog2(HASH_TABLE_SIZE);

    logic [HASH_CNT_WIDTH-1:0] hash_table [HASH_TABLE_SIZE-1:0];
    logic [HASH_IDX_WIDTH-1:0] hash_idx;

    assign hash_idx = key_i[HASH_IDX_WIDTH-1:0];

    assign hit_o = (hash_table[hash_idx] > 0);

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            for (int i = 0; i < HASH_TABLE_SIZE; i++) begin
                hash_table[i] <= '0;
            end
        end else if (clear_i) begin
            for (int i = 0; i < HASH_TABLE_SIZE; i++) begin
                hash_table[i] <= '0;
            end
        end else begin
            if (insert_i) begin
                hash_table[hash_idx] <= hash_table[hash_idx] + 1;
            end
            if (delete_i && hash_table[hash_idx] > 0) begin
                hash_table[hash_idx] <= hash_table[hash_idx] - 1;
            end
        end
    end

endmodule

