module cdc_fifo_gray #(
    parameter int unsigned LOG_DEPTH = 3,
    parameter type         DATA_T   = logic
)(
    input  logic  clk_src_i,
    input  logic  rst_src_ni,
    input  DATA_T data_src_i,
    input  logic  valid_src_i,
    output logic  ready_src_o,
    input  logic  clk_dst_i,
    input  logic  rst_dst_ni,
    output DATA_T data_dst_o,
    output logic  valid_dst_o,
    input  logic  ready_dst_i
);

    localparam int unsigned DEPTH      = 2**LOG_DEPTH;
    localparam int unsigned DATA_WIDTH = $bits(DATA_T);

    logic [LOG_DEPTH:0] wptr_bin_q, wptr_bin_d;
    logic [LOG_DEPTH:0] rptr_bin_q, rptr_bin_d;
    logic [LOG_DEPTH:0] wptr_gray_q, wptr_gray_d;
    logic [LOG_DEPTH:0] rptr_gray_q, rptr_gray_d;
    logic [LOG_DEPTH:0] wptr_gray_sync, rptr_gray_sync;

    DATA_T [DEPTH-1:0] mem;

    binary_to_gray #(.N(LOG_DEPTH+1)) i_b2g_wptr (
        .binary_i(wptr_bin_q),
        .gray_o  (wptr_gray_q)
    );

    binary_to_gray #(.N(LOG_DEPTH+1)) i_b2g_rptr (
        .binary_i(rptr_bin_q),
        .gray_o  (rptr_gray_q)
    );

    gray_to_binary #(.N(LOG_DEPTH+1)) i_g2b_wptr (
        .gray_i  (wptr_gray_sync),
        .binary_o(wptr_bin_d)
    );

    gray_to_binary #(.N(LOG_DEPTH+1)) i_g2b_rptr (
        .gray_i  (rptr_gray_sync),
        .binary_o(rptr_bin_d)
    );

    sync #(.STAGES(2)) i_sync_wptr (
        .clk_i    (clk_dst_i),
        .rst_ni   (rst_dst_ni),
        .serial_i (wptr_gray_q),
        .serial_o (wptr_gray_sync)
    );

    sync #(.STAGES(2)) i_sync_rptr (
        .clk_i    (clk_src_i),
        .rst_ni   (rst_src_ni),
        .serial_i (rptr_gray_q),
        .serial_o (rptr_gray_sync)
    );

    assign ready_src_o = (wptr_bin_q - rptr_bin_d) < DEPTH;

    always_ff @(posedge clk_src_i or negedge rst_src_ni) begin
        if (!rst_src_ni) begin
            wptr_bin_q <= '0;
            for (int i = 0; i < DEPTH; i++) begin
                mem[i] <= '0;
            end
        end else if (valid_src_i && ready_src_o) begin
            mem[wptr_bin_q[LOG_DEPTH-1:0]] <= data_src_i;
            wptr_bin_q <= wptr_bin_q + 1;
        end
    end

    assign valid_dst_o = (rptr_bin_q != wptr_bin_d);
    assign data_dst_o  = mem[rptr_bin_q[LOG_DEPTH-1:0]];

    always_ff @(posedge clk_dst_i or negedge rst_dst_ni) begin
        if (!rst_dst_ni) begin
            rptr_bin_q <= '0;
        end else if (valid_dst_o && ready_dst_i) begin
            rptr_bin_q <= rptr_bin_q + 1;
        end
    end

endmodule

