module id_queue #(
    parameter int unsigned CAPACITY = 8,
    parameter int unsigned DATA_WIDTH = 32,
    parameter type         data_t = logic [DATA_WIDTH-1:0],
    parameter int unsigned ID_WIDTH = 4,
    parameter type         id_t = logic [ID_WIDTH-1:0]
)(
    input  logic                     clk_i,
    input  logic                     rst_ni,
    input  logic                     flush_i,
    input  logic                     testmode_i,
    input  data_t                    data_i,
    input  id_t                      id_i,
    input  logic                     inp_valid_i,
    output logic                     inp_ready_o,
    input  id_t                      oup_id_i,
    output data_t                    data_o,
    output logic                     oup_valid_o,
    input  logic                     oup_ready_i,
    output logic                     exists_o,
    input  logic                     push_i
);

    localparam int unsigned CNT_WIDTH = $clog2(CAPACITY + 1);

    logic [CAPACITY-1:0] valid_q, valid_d;
    data_t [CAPACITY-1:0] data_q;
    id_t   [CAPACITY-1:0] id_q;
    logic [CAPACITY-1:0] head_oh;
    logic [CNT_WIDTH-1:0] usage_q, usage_d;

    assign exists_o = |(valid_q & (id_q == id_i));

    always_comb begin
        head_oh = '0;
        for (int i = 0; i < CAPACITY; i++) begin
            if (valid_q[i] && id_q[i] == oup_id_i) begin
                head_oh[i] = 1'b1;
            end
        end
    end

    assign oup_valid_o = |head_oh;

    always_comb begin
        data_o = '0;
        for (int i = 0; i < CAPACITY; i++) begin
            if (head_oh[i]) begin
                data_o = data_q[i];
            end
        end
    end

    always_comb begin
        valid_d = valid_q;
        usage_d = usage_q;

        if (flush_i) begin
            valid_d = '0;
            usage_d = '0;
        end else begin
            if (inp_valid_i && inp_ready_o) begin
                for (int i = 0; i < CAPACITY; i++) begin
                    if (!valid_d[i]) begin
                        valid_d[i] = 1'b1;
                        break;
                    end
                end
                usage_d = usage_q + 1;
            end
            if (oup_valid_o && oup_ready_i) begin
                for (int i = 0; i < CAPACITY; i++) begin
                    if (head_oh[i]) begin
                        valid_d[i] = 1'b0;
                    end
                end
                usage_d = usage_d - 1;
            end
        end
    end

    assign inp_ready_o = (usage_q < CAPACITY);

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            valid_q <= '0;
            usage_q <= '0;
            for (int i = 0; i < CAPACITY; i++) begin
                data_q[i] <= '0;
                id_q[i]   <= '0;
            end
        end else begin
            valid_q <= valid_d;
            usage_q <= usage_d;
            if (inp_valid_i && inp_ready_o) begin
                for (int i = 0; i < CAPACITY; i++) begin
                    if (!valid_q[i]) begin
                        data_q[i] <= data_i;
                        id_q[i]   <= id_i;
                        break;
                    end
                end
            end
        end
    end

endmodule

