module stream_arbiter_flushable #(
    parameter int unsigned N_INP = 2,
    parameter type         DATA_T = logic,
    parameter bit          ARBITER = 1'b1
)(
    input  logic  clk_i,
    input  logic  rst_ni,
    input  logic  flush_i,
    input  DATA_T [N_INP-1:0] data_i,
    input  logic  [N_INP-1:0] valid_i,
    output logic  [N_INP-1:0] ready_o,
    output DATA_T data_o,
    output logic  valid_o,
    input  logic  ready_i
);

    logic [$clog2(N_INP)-1:0] rr_q, rr_d;
    logic [$clog2(N_INP)-1:0] idx;
    logic [N_INP-1:0] gnt;

    rr_arb_tree #(
        .NumIn    (N_INP),
        .DataWidth($bits(DATA_T)),
        .ExtPrio  (1'b0),
        .AxiVldRdy(1'b1),
        .LockIn   (1'b0),
        .FairArb  (1'b0)
    ) i_rr_arb_tree (
        .clk_i  (clk_i),
        .rst_ni (rst_ni),
        .flush_i(flush_i),
        .rr_i   ('0),
        .req_i  (valid_i),
        .gnt_o  (gnt),
        .data_i (data_i),
        .gnt_i  (ready_i),
        .req_o  (valid_o),
        .data_o (data_o),
        .idx_o  (idx)
    );

    for (genvar i = 0; i < N_INP; i++) begin : gen_ready
        assign ready_o[i] = gnt[i];
    end

endmodule

