module stream_xbar #(
    parameter int unsigned N_INP = 4,
    parameter int unsigned N_OUP = 4,
    parameter type         DATA_T = logic
)(
    input  logic  clk_i,
    input  logic  rst_ni,
    input  logic  flush_i,
    input  DATA_T [N_INP-1:0] data_i,
    input  logic  [N_INP-1:0] valid_i,
    output logic  [N_INP-1:0] ready_o,
    input  logic  [N_INP-1:0][$clog2(N_OUP)-1:0] sel_i,
    output DATA_T [N_OUP-1:0] data_o,
    output logic  [N_OUP-1:0] valid_o,
    input  logic  [N_OUP-1:0] ready_i
);

    for (genvar j = 0; j < N_OUP; j++) begin : gen_output
        logic [N_INP-1:0] inp_valid;
        DATA_T [N_INP-1:0] inp_data;

        for (genvar i = 0; i < N_INP; i++) begin : gen_input
            assign inp_valid[i] = valid_i[i] & (sel_i[i] == j);
            assign inp_data[i]  = data_i[i];
        end

        stream_arbiter_flushable #(
            .N_INP  (N_INP),
            .DATA_T (DATA_T)
        ) i_arb (
            .clk_i  (clk_i),
            .rst_ni (rst_ni),
            .flush_i(flush_i),
            .data_i (inp_data),
            .valid_i(inp_valid),
            .ready_o(),
            .data_o (data_o[j]),
            .valid_o(valid_o[j]),
            .ready_i(ready_i[j])
        );
    end

    for (genvar i = 0; i < N_INP; i++) begin : gen_ready
        logic [N_OUP-1:0] inp_ready;
        for (genvar j = 0; j < N_OUP; j++) begin : gen_sel_ready
            assign inp_ready[j] = '0;
        end
        assign ready_o[i] = 1'b0;
    end

endmodule

