module mem_to_banks_detailed #(
    parameter int unsigned AddrWidth = 32,
    parameter int unsigned DataWidth = 32,
    parameter int unsigned NumBanks  = 2,
    parameter type         addr_t    = logic [AddrWidth-1:0],
    parameter type         data_t    = logic [DataWidth-1:0]
)(
    input  logic  clk_i,
    input  logic  rst_ni,
    input  logic  req_i,
    output logic  gnt_o,
    input  addr_t addr_i,
    input  logic  write_i,
    input  data_t wdata_i,
    output logic  rvalid_o,
    output data_t rdata_o,
    output logic  [NumBanks-1:0] bank_req_o,
    input  logic  [NumBanks-1:0] bank_gnt_i,
    output addr_t [NumBanks-1:0] bank_addr_o,
    output logic  [NumBanks-1:0] bank_write_o,
    output data_t [NumBanks-1:0] bank_wdata_o,
    input  logic  [NumBanks-1:0] bank_rvalid_i,
    input  data_t [NumBanks-1:0] bank_rdata_i
);

    logic [$clog2(NumBanks)-1:0] bank_sel;

    assign bank_sel   = addr_i[$clog2(NumBanks)-1:0];
    assign gnt_o      = bank_gnt_i[bank_sel];
    assign rvalid_o   = bank_rvalid_i[bank_sel];
    assign rdata_o    = bank_rdata_i[bank_sel];

    for (genvar i = 0; i < NumBanks; i++) begin : gen_bank
        assign bank_req_o[i]   = req_i & (bank_sel == i);
        assign bank_addr_o[i]  = addr_i;
        assign bank_write_o[i] = write_i;
        assign bank_wdata_o[i] = wdata_i;
    end

endmodule

