module fifo_v2 #(
    parameter bit           FALL_THROUGH = 1'b0,
    parameter int unsigned  DATA_WIDTH   = 32,
    parameter int unsigned  DEPTH        = 8,
    parameter int unsigned  THRESHOLD    = 1
)(
    input  logic                    clk_i,
    input  logic                    rst_ni,
    input  logic                    flush_i,
    input  logic                    testmode_i,
    output logic                    full_o,
    output logic                    empty_o,
    output logic                    threshold_o,
    input  logic [DATA_WIDTH-1:0]   data_i,
    input  logic                    push_i,
    output logic [DATA_WIDTH-1:0]   data_o,
    input  logic                    pop_i
);

    logic [$clog2(DEPTH)-1:0] usage;

    fifo_v3 #(
        .FALL_THROUGH(FALL_THROUGH),
        .DATA_WIDTH  (DATA_WIDTH),
        .DEPTH       (DEPTH)
    ) i_fifo_v3 (
        .clk_i     (clk_i),
        .rst_ni    (rst_ni),
        .flush_i   (flush_i),
        .testmode_i(testmode_i),
        .full_o    (full_o),
        .empty_o   (empty_o),
        .usage_o   (usage),
        .data_i    (data_i),
        .push_i    (push_i),
        .data_o    (data_o),
        .pop_i     (pop_i)
    );

    assign threshold_o = (usage >= THRESHOLD[$clog2(DEPTH)-1:0]);

endmodule

