module prioarbiter #(
    parameter int unsigned N_INP = 2
)(
    input  logic          clk_i,
    input  logic          rst_ni,
    input  logic [N_INP-1:0] req_i,
    output logic [N_INP-1:0] gnt_o,
    input  logic          ack_i
);

    logic [N_INP-1:0] gnt;

    always_comb begin
        gnt = '0;
        for (int unsigned i = 0; i < N_INP; i++) begin
            if (req_i[i]) begin
                gnt[i] = 1'b1;
                break;
            end
        end
    end

    assign gnt_o = gnt;

endmodule

